    "Сначала подготовьте стороннюю часть, затем вернитесь и нажмите «Проверить и продолжить».",
  "bots.setup.callbackUrlTitle": "URL обратного вызова",
  "bots.setup.callbackUrlDescription.webhook":
    "Ваша внешняя система должна отправлять входящие колбэки сообщений на этот адрес. Асинхронные исходящие ответы по-прежнему используют URL вебхука, указанный слева.",
  "bots.setup.callbackUrlDescription.webhookBind":
    "Привязка вебхука использует ту же конечную точку: отправьте сюда приватный колбэк-запрос с text = /bind <code>.",
  "bots.setup.guide.telegram.create.1": "Откройте @BotFather в Telegram и создайте нового бота.",
  "bots.setup.guide.telegram.create.2":
    "Скопируйте HTTP API-токен, возвращённый BotFather, и вставьте его в эту форму.",
  "bots.setup.guide.telegram.create.3":
    "Полезно сразу открыть личный чат с ботом: команду привязки нужно отправить именно туда.",
  "bots.setup.guide.telegram.bind.1":
    "Вернитесь в Telegram и откройте личный чат с созданным ботом.",
  "bots.setup.guide.telegram.bind.2":
    "Если чат ещё не начат, сначала нажмите Start или отправьте любое сообщение, затем отправьте {command}.",
  "bots.setup.guide.telegram.bind.3": "Вернитесь сюда после того, как Telegram подтвердит успешную привязку.",
  "bots.setup.guide.weixin.create.1":
    "Запустите вход по QR-коду Weixin, отсканируйте QR-код в Weixin и подтвердите на телефоне.",
  "bots.setup.guide.weixin.create.2":
    "ZCode автоматически сохраняет bot_token, возвращённый iLink; после сканирования отправьте боту любое сообщение в Weixin, чтобы активировать чат.",
  "bots.setup.guide.weixin.create.3":
    "ZCode использует встроенный клиент iLink: `/ilink/bot/getupdates` для long polling и `/ilink/bot/sendmessage` для ответов.",
  "bots.setup.guide.weixin.bind.1": "Откройте личный чат Weixin, который хотите привязать.",
  "bots.setup.guide.weixin.bind.2": "Отправьте {command}.",
  "bots.setup.guide.weixin.bind.3":
    "После успешной привязки вернитесь сюда, чтобы завершить настройку рабочей области и значений CLI по умолчанию.",
  "bots.setup.guide.feishu.create.1":
    "Создайте собственное приложение в консоли разработчика Feishu/Lark и включите возможности бота.",
  "bots.setup.guide.feishu.create.2":
    "Скопируйте App ID и App Secret, затем включите события постоянного подключения для `im.message.receive_v1` и действия карточек.",
  "bots.setup.guide.feishu.create.3":
    "Выберите здесь подходящий домен Feishu или Lark, затем вставьте учётные данные в форму.",
  "bots.setup.guide.feishu.bind.1":
    "Установите приложение в свою организацию и откройте личный чат с ботом.",
  "bots.setup.guide.feishu.bind.2": "Отправьте {command} в этом личном чате.",
  "bots.setup.guide.feishu.bind.3":
    "После успешной привязки вернитесь сюда, чтобы завершить настройку рабочей области и значений CLI по умолчанию.",
  "bots.setup.guide.webhook.create.1":
    "Режим вебхука не требует нативного бота в стороннем продукте; вашей интеграции достаточно отправлять сообщения в ZCode методом POST.",
  "bots.setup.guide.webhook.create.2":
    "Сначала задайте общий секрет; если нужны асинхронные ответы, также добавьте исходящий URL вебхука.",
  "bots.setup.guide.webhook.create.3":
    "Используйте один стабильный userId для каждого внешнего пользователя, чтобы привязка и будущий контекст указывали на одного и того же человека.",
  "bots.setup.guide.webhook.bind.1":
    "Отправьте POST-колбэк личного сообщения на конечную точку ZCode `/api/bots/webhook`.",
  "bots.setup.guide.webhook.bind.2":
    "Тело запроса должно как минимум содержать этот botId, стабильный userId, `chatType: \"private\"`, а в text передать {command}.",
  "bots.setup.guide.webhook.bind.3":
    "Если бот использует секрет, также отправьте `x-zcode-bot-secret`; затем вернитесь сюда после успешной привязки.",
