  "settings.modelProvider.fieldHelp": "О поле {field}",
  "settings.modelProvider.help.contextWindow":
    "Объём контекста (в токенах), который модель может обработать за один раз. ZCode использует это значение для управления контекстом.\nНе превышайте фактический лимит модели.",
  "settings.modelProvider.help.maxOutputTokens":
    "Максимальное количество токенов, которое может сгенерировать один запрос к модели.\nНе превышайте фактический лимит модели.",
  "settings.modelProvider.help.inputModalities":
    "Задайте типы контента, которые принимает модель:\n\n- **Текст**: принимает текстовый контент. Обязательно.\n- **Изображения**: принимает изображения.\n- **Видео**: принимает видео.\n- **PDF**: принимает PDF-документы напрямую.",
  "settings.modelProvider.help.outputModalities":
    "Тип контента в ответах модели. Сейчас поддерживается только текст.",
  "settings.modelProvider.help.capabilities":
    "- **Структурированный вывод**: поддержка ограничений JSON Schema на поля, типы и структуру вывода.\n- **Встроенный веб-поиск**: поддержка встроенного веб-поиска в API модели.\n- **Системные сообщения посреди диалога**: поддержка вставки системных инструкций во время диалога.\n\nНе включайте возможности, которые модель не поддерживает.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Задайте уровни рассуждений, доступные в чате. **Они должны быть упорядочены от меньшего уровня рассуждений к большему**.\nНе настраивайте уровни рассуждений, которые модель не поддерживает.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "Используйте CEL-выражение, чтобы сопоставить текущий уровень рассуждений (`reasoningLevel`) с полями запроса к API модели. Возвращённый выражением JSON-объект объединяется с телом исходящего запроса.",
  "settings.modelProvider.help.advanced":
    "**Схема инструментов MFJS**: включает совместимость с Moonshot Flavored JSON Schema, используемую API моделей Kimi от Moonshot. Включайте, только если API модели требует этот формат.",
  "settings.modelProvider.help.followRecommendedConfig":
    "Подбирает рекомендованную конфигурацию по ID модели, Base URL и формату API. ZCode постоянно обновляет рекомендации и автоматически синхронизирует их.\nПри ручном изменении настройка переходит в ручное управление и перестаёт следовать рекомендациям; остальные настройки остаются под управлением умной конфигурации.",
  "settings.modelProvider.modelDefaultsLoaded": "Для этой модели подобрана умная конфигурация",
